head.script:
scwin.regMode;
scwin.gEmpNo = js_emp_no;
scwin.gIsurCd;
scwin.gChrgNm;
scwin.gComAbbrv;
scwin.gChrgTpNm;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_1);
        scwin.getParentValue();
        await scwin.checkLngtrmContsvcPrn();
        await scwin.init();
        // fn_setYear();

        if (scwin.regMode === 'MOD') {
            await scwin.readInfo(); // 기본정보 불러오기

        }
        $c.stf.doLogSave('ULDSTF30629.xml', SCREN_PROCS_TP_CD_01);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30632.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    txb_Seq.hide();
    txb_Isur_Cd.hide();
    txb_Chrg_Nm.show("");
    scwin.gComAbbrv = frame.opener.scwin.gComAbbrv;
    scwin.gChrgTpNm = frame.opener.scwin.gChrgTpNm;
    txb_Com_Abbrv.setValue(scwin.gComAbbrv);
    txb_Chrg_Tp_Nm.setValue(scwin.gChrgTpNm);
    if (scwin.regMode === "REG") {
        txb_Isur_Cd.setValue(scwin.gIsurCd);
        txb_Chrg_Nm.setValue(scwin.gChrgNm);
        // setObjectValue(rdo_Lngtrm_Contsvc_Corr_Yn, "Y");

    } else {
        btn_Save.setBackgroundImage("../img/btn_modify.gif");
        btn_Del.show("");
    }

    // 가우스헤더 셋팅
    const sbmOptions = {
        id : "sbm_dts_procs",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_procs=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // dts_procs.AddRow();

};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_lngtrm_OnSuccess
 * @description lngtrm On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_lngtrm_OnSuccess = async function() {
    try {
        await $c.win.alert("성공적으로 처리 되었습니다.");
        await $c.win.closePopup();
        // 부모창 reload 처리해야함
        $c.frame.path("../").fn_Search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30632.trs_lngtrm_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_lngtrm_OnFail
 * @description lngtrm On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_lngtrm_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", '장기근속자'));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30632.trs_lngtrm_OnFail" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30632.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.procs();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30632.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name dts_lngtrm_OnLoadCompleted
 * @description dts_lngtrm 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_lngtrm_OnLoadCompleted = function(rowcount) {

};

/**
 * @method
 * @name btn_Del_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Del_onclick = async function() {
    try {
        await scwin.delete();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30632.btn_Del_onclick" });
    }
};

/**
 * @method
 * @name rdo_Lngtrm_Contsvc_Corr_Yn_onclick
 * @description rdo_Lngtrm_Contsvc_Corr_Yn 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_Lngtrm_Contsvc_Corr_Yn_onclick = function() {

};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name readInfo
 * @description 선택한 정보 값 셋팅
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readInfo = async function() {
    const sbmOptions = {
        id : "sbm_dts_lngtrm",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_lngtrm=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name procs
 * @description 등록 및 수정 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.procs = async function() {
    const vRdo_Lngtrm_Contsvc_Corr_Yn = rdo_Lngtrm_Contsvc_Corr_Yn.getValue();
    const vTxb_Lngtrm_Contsvc_Bas_Yy = txb_Lngtrm_Contsvc_Bas_Yy.getValue();
    const emp_no = scwin.gEmpNo;
    if (vRdo_Lngtrm_Contsvc_Corr_Yn === "") {
        await $c.win.alert("장기근속자 해당여부를 선택하십시오.");
        rdo_Lngtrm_Contsvc_Corr_Yn.focus();
        return;
    }
    if (vTxb_Lngtrm_Contsvc_Bas_Yy === "") {
        await $c.win.alert("기준년도를 입력하십시오.");
        txb_Lngtrm_Contsvc_Bas_Yy.focus();
        return;
    }
    if (isNaN(txb_Lngtrm_Contsvc_Bas_Yy.getValue())) {
        // 숫자가 아니다.
        const msg = $c.stf.getMessageParam("MSG-0910", "기준년도");
        await $c.win.alert(msg);
        txb_Lngtrm_Contsvc_Bas_Yy.focus();
        return;
    }
    if (txb_Lngtrm_Contsvc_Bas_Yy.getValue() !== "") {
        // 일자 체크
        if (txb_Lngtrm_Contsvc_Bas_Yy.getValue().length < 4) {
            await $c.win.alert("기준년도를 올바르게 입력하십시오.");
            txb_Lngtrm_Contsvc_Bas_Yy.focus();
            return;
        }
    }
    if (!$c.stf.checkMaxLength(txa_Contsvc_Bz_Hist_Contn, 2000, "공시담당자 업무이력 비고")) return false;
    dts_procs.insertRow();
    dts_procs.setCellData(1, "ISUR_CD", txb_Isur_Cd.getValue());
    dts_procs.setCellData(1, "LNGTRM_CONTSVC_CORR_YN", rdo_Lngtrm_Contsvc_Corr_Yn.getValue());
    dts_procs.setCellData(1, "CHRG_NM", scwin.gChrgNm);
    dts_procs.setCellData(1, "CONTSVC_BZ_HIST_CONTN", txa_Contsvc_Bz_Hist_Contn.getValue());
    dts_procs.setCellData(1, "LNGTRM_CONTSVC_BAS_YY", txb_Lngtrm_Contsvc_Bas_Yy.getValue());
    dts_procs.setCellData(1, "SEQ", txb_Seq.getValue());
    // 20181116
    // getObjectValue(txb_Chrg_Nm)  -> gChrgNm  으로 변경
    // getObjectValue 는 trim 을 하고 있어서 목록의 이름과 맞지 않음으로 인해 변경

    let tmpStr;
    let vMethod;
    if (scwin.regMode === 'REG') {
        tmpStr = "저장 하시겠습니까?";
        vMethod = "insertLngtrmContsvcPrn";
    } else if (scwin.regMode === 'MOD') {
        tmpStr = "수정 하시겠습니까?";
        vMethod = "updateLngtrmContsvcPrn";
    }
    let vAnswer = confirm(tmpStr);
    if (vAnswer === true) {
        trs_lngtrm.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_lngtrm",
            action : "/ListedCompany.do",
            ref : "dts_procs",
            target : "trs_lngtrm=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name delete
 * @description 삭제
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    dts_procs.insertRow();
    dts_procs.setCellData(1, "SEQ", txb_Seq.getValue());
    let tmpStr;
    let vMethod;
    vMethod = "deleteLngtrmContsvcPrn";
    tmpStr = "삭제 하시겠습니까?";
    let vAnswer = confirm(tmpStr);
    if (vAnswer === true) {
        trs_lngtrm.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_lngtrm",
            action : "/ListedCompany.do",
            ref : "dts_procs",
            target : "trs_lngtrm=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name checkLngtrmContsvcPrn
 * @description 장기근속자 등록 가능 여부 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkLngtrmContsvcPrn = async function() {
    let vPOS_YN;
    const sbmOptions = {
        id : "sbm_dts_check_lngtrm",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_check_lngtrm=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    vPOS_YN = dts_check_lngtrm.getCellData(1, "POS_YN");
    if (vPOS_YN === "N") {
        scwin.regMode = 'MOD';
    } else {
        scwin.regMode = 'REG';
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParentValue
 * @description 부모창에서 필요변수 저장
 * @returns {void}
 * @hidden N
 */
scwin.getParentValue = function() {
    scwin.regMode = "REG";
    btn_Del.hide();
    scwin.gIsurCd = frame.opener.scwin.gIsurCd;
    scwin.gChrgNm = frame.opener.scwin.gChrgNm;
    scwin.gComAbbrv = frame.opener.scwin.gComAbbrv;
    scwin.gChrgTpNm = frame.opener.scwin.gChrgTpNm;
};

/**
 * @method
 * @name setYear
 * @description default 현재년도
 * @returns {void}
 * @hidden N
 */
scwin.setYear = function() {
    // default 현재년도
    const ToDay = new Date();
    const yyyy = parseInt(ToDay.getYear(), 10);
    const minYear = '2010';
    const maxYear = yyyy + 10;
    let str = "^전체";
    for (let i = maxYear; i >= minYear; i--) {
        str += "," + i + "%^" + i;
    }
    // alert(str);
    cmb_New_Edu_Complt_Yy.CBData = str;
    let yyyy_etc;
    yyyy_etc = gNewEduCompltYy;
};
